  const [summary, setSummary] = reactExports.useState(null);
  const [ingredients, setIngredients] = reactExports.useState([]);
  const [query, setQuery] = reactExports.useState("");
  const [filter, setFilter] = reactExports.useState("all");
  const [sort, setSort] = reactExports.useState("worst");
  const [editor, setEditor] = reactExports.useState(null);
  const [pickQuery, setPickQuery] = reactExports.useState("");
  const [period, setPeriod] = reactExports.useState("day");
  const [resetAt, setResetAt] = reactExports.useState(0);
  const [costMethod, setCostMethod] = reactExports.useState("");
  const [confirmAsk, confirmDialog] = useConfirm();
  reactExports.useEffect(() => {
    void window.pos.stock.costingMethod().then((r) => { if (r.success) setCostMethod(r.data.method); });
  }, []);
  reactExports.useEffect(() => {
    void window.pos.settings.getAll().then((r) => { if (r.success) setResetAt(Number(r.data.settings["costing.resetAt"]) || 0); });
  }, []);
  const since = psPeriodStart(period, resetAt);

  const reload = reactExports.useCallback(async () => {
    const [costRes, ingRes] = await Promise.all([
      window.pos.inventory.costing(since, costMethod),
      window.pos.inventory.ingredients()
    ]);
    if (costRes.success) {
      setRows(costRes.data.items ?? []);
      setSummary(costRes.data.summary ?? null);
    }
    if (ingRes.success) setIngredients(ingRes.data.ingredients ?? []);
  }, [since, costMethod]);

  reactExports.useEffect(() => { void reload(); }, [reload]);
  const [busy, run] = useOpsAction(reload);

  const pct = (bp) => (Number(bp) / 100).toFixed(1) + "%";
  const units = ["kg", "q", "l", "ədəd", "qab"];
  const unitLabel = (u) => ({ kg: "kg", q: "qram", l: "litr", "ədəd": "ədəd", qab: "qab" }[u] || u);

  /** Qty in DB milli for the ingredient unit. Grams use unit=q where 1 q = 1 milli of q. */
  const lineQtyMilli = (line) => {
    const n = opsNum(line.qty);
    if (!(n > 0)) return 0;
    // Grams: 150 q = 0.150 kg = 150 milli of a kg-priced ingredient.
    if (line.unit === "q" || line.unit === "ml") return Math.round(n);
    return Math.round(n * 1000);
  };

  const lineCostMinor = (line) => {
    const qtyMilli = lineQtyMilli(line);
    if (qtyMilli <= 0) return 0;
    const unitCost = Number(line.unitCostMinor) || 0;
    return Math.round(qtyMilli * unitCost / 1000);
  };

  const state = (row) => {
    if (!row.hasRecipe) return { key: "norecipe", label: "Kalkulyasiya yoxdur", color: "var(--ps-danger)" };
    if (row.unpriced) return { key: "unpriced", label: "Maya dəyəri yazılmayıb", color: "var(--ps-warn)" };
    if ((row.marginMinor ?? 0) < 0) return { key: "losing", label: "Zərər", color: "var(--ps-danger)" };
    if ((row.foodCostBp ?? 0) > 3500) return { key: "high", label: "Maya yüksək", color: "#a16207" };
    return { key: "ok", label: "Normal", color: "var(--ps-ok)" };
  };

